insert into learning.learning_paths(id,title,objective,revision,subject,overview_note_id) values ('algorithm-foundations','ACM Algorithms — Foundations to Intermediate','One staged learning workflow for ACM input/output, walks, DP, backtracking, search, data structures and graph models.',1,'algorithms',(select id from learning.notes where title='ACM Curriculum — Roadmap' and deleted_at is null));
insert into learning.path_lessons(id,path_id,title,objective,position,reading_note_id,stage,experiment_plan,experiment_setup) values ('acm-io','algorithm-foundations','ACM Input, Output and Boundaries','把 stdin 解析、算法规则、stdout 分开；稳定处理数字列表和计数输出。',0,(select id from learning.notes where title='ACM Curriculum — ACM Input, Output and Boundaries' and deleted_at is null),'01 · ACM Foundations','["只解析一份题面样例，打印 token、类型和数组长度，不开始算法。", "独立写一个计数小函数，用目标不存在、重复、单元素验证。", "组合解析与算法，stdout 只输出答案；练习 print(*items) 输出数字列表。", "用 StringIO 模拟两种空白布局，与手算答案核对；不擅自添加多组输入规则。"]'::jsonb,'');
insert into learning.lesson_resources(lesson_id,kind,reference,revision) values ('acm-io','oj','159:count-target-occurrences','catalog-v1');
insert into learning.path_lessons(id,path_id,title,objective,position,reading_note_id,stage,experiment_plan,experiment_setup) values ('acm-recursion','algorithm-foundations','Recursion and the Call Stack','用一个明确变小的子问题和出口，解释递归返回值与调用栈。',1,(select id from learning.notes where title='ACM Curriculum — Recursion and the Call Stack' and deleted_at is null),'01 · ACM Foundations','["不用代码画三层调用和返回路径，标出空范围出口。", "仅在小数组上打印 enter/return，观察调用顺序与返回顺序。", "用索引表示剩余范围，再与切片写法比较实际复制成本。", "改写为循环并核对答案；长输入只讨论递归深度，不靠修改限制规避。"]'::jsonb,'');
insert into learning.lesson_resources(lesson_id,kind,reference,revision) values ('acm-recursion','oj','157:recursive-array-sum','catalog-v1');
insert into learning.path_lessons(id,path_id,title,objective,position,reading_note_id,stage,experiment_plan,experiment_setup) values ('acm-line-walk','algorithm-foundations','One-Dimensional Walk DP','用一维走格子推导状态、最后一步、边界和计算顺序。',2,(select id from learning.notes where title='ACM Curriculum — One-Dimensional Walk DP' and deleted_at is null),'02 · Walks and Dynamic Programming','["手列 n=1..4 的路径，画递归树。", "打印朴素递归的重复调用，再增加缓存比较调用数量。", "逐格填 dp 表，核对每格依赖已经计算。", "尝试只保留前两个状态，解释压缩后每个变量的含义。"]'::jsonb,'');
insert into learning.lesson_resources(lesson_id,kind,reference,revision) values ('acm-line-walk','oj','99:climbing-stairs','catalog-v1');
insert into learning.path_lessons(id,path_id,title,objective,position,reading_note_id,stage,experiment_plan,experiment_setup) values ('acm-grid-walk','algorithm-foundations','Two-Dimensional Walk DP','从只能向右或向下的网格，推导二维路径计数。',3,(select id from learning.notes where title='ACM Curriculum — Two-Dimensional Walk DP' and deleted_at is null),'02 · Walks and Dynamic Programming','["在纸上标坐标、允许方向、起终点，列出全部小路径。", "只填第一行第一列并预测边界值。", "逐格打印上方、左方与当前结果，对照手算表。", "测试 1×1、单行、单列，再尝试按列滚动存储。"]'::jsonb,'');
insert into learning.lesson_resources(lesson_id,kind,reference,revision) values ('acm-grid-walk','oj','111:unique-paths','catalog-v1');
insert into learning.path_lessons(id,path_id,title,objective,position,reading_note_id,stage,experiment_plan,experiment_setup) values ('acm-knapsack-01','algorithm-foundations','0/1 Knapsack','重建喜欢的 0/1 背包过程：选或不选，先二维状态再理解倒序容量。',4,(select id from learning.notes where title='ACM Curriculum — 0/1 Knapsack' and deleted_at is null),'02 · Walks and Dynamic Programming','["枚举两个物品的所有选/不选组合，预测每个容量答案。", "填写二维 DP 并标注每个值来自上一行的哪一格。", "压缩为一维，故意正序与倒序对照，看正序如何重复使用物品。", "把 max 价值改为布尔可达，推导等和子集的目标，再进入 OJ 110。"]'::jsonb,'');
insert into learning.lesson_resources(lesson_id,kind,reference,revision) values ('acm-knapsack-01','oj','110:partition-equal-subset-sum','catalog-v1');
insert into learning.path_lessons(id,path_id,title,objective,position,reading_note_id,stage,experiment_plan,experiment_setup) values ('acm-backtracking','algorithm-foundations','Backtracking: Subsets','从已学到的回溯继续：选择、递归、撤销；区分答案副本和活动路径。',5,(select id from learning.notes where title='ACM Curriculum — Backtracking: Subsets' and deleted_at is null),'03 · Backtracking','["手画两元素决策树，给每条边标选择与撤销。", "只打印 enter/choose/undo，观察返回后 path 恢复。", "故意保存同一个 path 引用，再与副本比较输出差异。", "增加第三个元素，按当前 OJ 的分组和排序合同格式化输出。"]'::jsonb,'');
insert into learning.lesson_resources(lesson_id,kind,reference,revision) values ('acm-backtracking','oj','67:subsets','catalog-v1');
insert into learning.path_lessons(id,path_id,title,objective,position,reading_note_id,stage,experiment_plan,experiment_setup) values ('acm-permutations','algorithm-foundations','Backtracking: Permutations and Constraints','区分子集的 start 与排列的 used，并理解局部合法性剪枝。',6,(select id from learning.notes where title='ACM Curriculum — Backtracking: Permutations and Constraints' and deleted_at is null),'03 · Backtracking','["把排列树与子集树并排画出，说明下一步候选集合不同。", "打印 used 与 path，验证添加/撤销成对出现。", "给出禁止相邻某两项的明确训练约束，先枚举再尝试提前剪枝。", "核对全部无重复排列后，讨论重复值与同层去重，先不混入未学规则。"]'::jsonb,'');
insert into learning.lesson_resources(lesson_id,kind,reference,revision) values ('acm-permutations','oj','70:permutations','catalog-v1');
insert into learning.path_lessons(id,path_id,title,objective,position,reading_note_id,stage,experiment_plan,experiment_setup) values ('acm-grid-dfs','algorithm-foundations','Grid DFS and Connected Components','把回溯搜索树的经验转为可达性搜索，理解 visited 与连通块。',7,(select id from learning.notes where title='ACM Curriculum — Grid DFS and Connected Components' and deleted_at is null),'04 · Search and Trees','["只枚举当前坐标四个邻居，过滤越界和非 #。", "用显式 stack 搜索一个块，打印首次发现和 visited。", "加入外层扫描，只在未访问 # 上增加块数。", "与手算核对全空、全连通、单行与斜接触，讨论递归深度。"]'::jsonb,'');
insert into learning.lesson_resources(lesson_id,kind,reference,revision) values ('acm-grid-dfs','oj','154:grid-component-count','catalog-v1');
insert into learning.path_lessons(id,path_id,title,objective,position,reading_note_id,stage,experiment_plan,experiment_setup) values ('acm-grid-bfs','algorithm-foundations','Grid BFS and Distance Layers','用 FIFO 搜索相同区域，并在等权移动下建立距离层。',8,(select id from learning.notes where title='ACM Curriculum — Grid BFS and Distance Layers' and deleted_at is null),'04 · Search and Trees','["用 deque 演示先进先出，再与 stack 顺序比较。", "在同一小网格打印 BFS 与 DFS 轨迹，对照可达集合。", "额外记录 distance，按层解释首次到达的距离。", "用障碍、无路、起终点相同验证距离实验；OJ 80 按它的 0/1 符号计数。"]'::jsonb,'');
insert into learning.lesson_resources(lesson_id,kind,reference,revision) values ('acm-grid-bfs','oj','80:number-of-islands','catalog-v1');
insert into learning.path_lessons(id,path_id,title,objective,position,reading_note_id,stage,experiment_plan,experiment_setup) values ('acm-multi-source-bfs','algorithm-foundations','Multi-Source BFS and Simultaneous Spread','理解多个起点同时扩散，不把起点各自搜索再串联。',9,(select id from learning.notes where title='ACM Curriculum — Multi-Source BFS and Simultaneous Spread' and deleted_at is null),'04 · Search and Trees','["把所有源点同时标成距离 0，手画下一层。", "打印队列一层开始/结束，核对当前时间。", "加入障碍隔开一个新鲜格，核对剩余计数与 -1。", "比较没有新鲜、没有源点、多个源点，进入实际整数网格 OJ。"]'::jsonb,'');
insert into learning.lesson_resources(lesson_id,kind,reference,revision) values ('acm-multi-source-bfs','oj','84:rotting-oranges','catalog-v1');
insert into learning.path_lessons(id,path_id,title,objective,position,reading_note_id,stage,experiment_plan,experiment_setup) values ('acm-tree-traversal','algorithm-foundations','Tree Traversal and Recursive Returns','识别树的父子结构、三种遍历顺序与层序输入。',10,(select id from learning.notes where title='ACM Curriculum — Tree Traversal and Recursive Returns' and deleted_at is null),'04 · Search and Trees','["只用三个节点对象画结构，不读取输入。", "打印递归 enter/return，标记三处可能的记录位置。", "解析实际 level-order token，测试缺左子、缺右子，不机械套完全树数组索引。", "把结果按三行输出，与迭代 stack 和 BFS 层序作概念比较。"]'::jsonb,'');
insert into learning.lesson_resources(lesson_id,kind,reference,revision) values ('acm-tree-traversal','oj','165:recursive-tree-traversals','catalog-v1');
insert into learning.path_lessons(id,path_id,title,objective,position,reading_note_id,stage,experiment_plan,experiment_setup) values ('acm-prefix-counts','algorithm-foundations','Prefix Counts and Road Cuts','统计前缀中的类别数量，枚举所有切口；把 360 回忆不确定条件与训练合同分开。',11,(select id from learning.notes where title='ACM Curriculum — Prefix Counts and Road Cuts' and deleted_at is null),'05 · Prefix Statistics','["画 n+1 个切口，列出前缀 0/1 数量，核对 prefix[0]。", "只计算一个 [left,right) 区间某类字符数量，与直接 count 比较。", "逐个切口打印左右人数和满意数，用两倍计数避免奇数向下取整。", "先列合法切口再比较 abs(2*i-n)，测试全左/全右与平局；OJ 190 完成独立区间和程序。"]'::jsonb,'');
insert into learning.lesson_resources(lesson_id,kind,reference,revision) values ('acm-prefix-counts','oj','190:static-range-sum-queries','catalog-v1');
insert into learning.path_lessons(id,path_id,title,objective,position,reading_note_id,stage,experiment_plan,experiment_setup) values ('acm-prefix-frequency','algorithm-foundations','Prefix Sum Frequency','根据前缀差找到目标和区间，统计较早前缀值出现次数。',12,(select id from learning.notes where title='ACM Curriculum — Prefix Sum Frequency' and deleted_at is null),'05 · Prefix Statistics','["枚举全部小区间并手算目标和。", "用列表保存历史前缀，打印当前需要的值与匹配数量。", "换成频次字典，先查询后登记，比较重复值与全零数组。", "把小规模暴力结果作为对照，再写 OJ 192 完整程序。"]'::jsonb,'');
insert into learning.lesson_resources(lesson_id,kind,reference,revision) values ('acm-prefix-frequency','oj','192:count-subarrays-with-target-sum','catalog-v1');
insert into learning.path_lessons(id,path_id,title,objective,position,reading_note_id,stage,experiment_plan,experiment_setup) values ('acm-difference','algorithm-foundations','Difference Arrays and Range Updates','用端点变化表达区间加法，区分查询用前缀与更新用差分。',13,(select id from learning.notes where title='ACM Curriculum — Difference Arrays and Range Updates' and deleted_at is null),'05 · Prefix Statistics','["手写原数组对应的差分，累加恢复。", "只做一次区间更新，逐项比较暴力与差分结果。", "叠加两个重叠、负增量和末端更新，打印差分端点。", "所有更新完成后统一恢复，核对实际 OJ 的 n/q 输入。"]'::jsonb,'');
insert into learning.lesson_resources(lesson_id,kind,reference,revision) values ('acm-difference','oj','191:range-addition-reconstruction','catalog-v1');
insert into learning.path_lessons(id,path_id,title,objective,position,reading_note_id,stage,experiment_plan,experiment_setup) values ('acm-undirected','algorithm-foundations','Undirected Graphs and Connectivity','从网格隐式邻居变为双向邻接表，理解连通性、环和传球状态的边界。',14,(select id from learning.notes where title='ACM Curriculum — Undirected Graphs and Connectivity' and deleted_at is null),'06 · Graph Models','["逐行构建邻接表，核对边被登记两次。", "从一个起点 DFS/BFS，比较可达集合。", "外层遍历未访问节点，计数连通块。", "额外实验权重 <=w 过滤、单边、三角环与带尾巴的环，区分传球选择合同。"]'::jsonb,'');
insert into learning.lesson_resources(lesson_id,kind,reference,revision) values ('acm-undirected','oj','90:number-of-connected-components-in-an-undirected-graph','catalog-v1');
insert into learning.path_lessons(id,path_id,title,objective,position,reading_note_id,stage,experiment_plan,experiment_setup) values ('acm-dsu','algorithm-foundations','Disjoint Set Union','用集合代表和合并回答连通性，理解冗余边而非搜索访问顺序。',15,(select id from learning.notes where title='ACM Curriculum — Disjoint Set Union' and deleted_at is null),'06 · Graph Models','["只打印每个点当前父节点与 find 代表。", "每次合并前后列出集合成员，对比 BFS 连通性。", "加入冗余边并判断两端是否早已同组。", "增加路径压缩，解释父树变化但集合成员不变。"]'::jsonb,'');
insert into learning.lesson_resources(lesson_id,kind,reference,revision) values ('acm-dsu','oj','91:redundant-connection','catalog-v1');
insert into learning.path_lessons(id,path_id,title,objective,position,reading_note_id,stage,experiment_plan,experiment_setup) values ('acm-directed','algorithm-foundations','Directed Graphs and Topological Order','用依赖方向、入度和可执行集合解释有向图的顺序与环。',16,(select id from learning.notes where title='ACM Curriculum — Directed Graphs and Topological Order' and deleted_at is null),'06 · Graph Models','["手写邻接表和入度，把入度与出度分开。", "用 queue 观察依赖解除和首次变为 0 的时机。", "多起点换成 heap，每次选编号最小的可用点。", "检测剩余节点，测试独立节点、自环、环加孤立点，并按 OJ 输出 CYCLE。"]'::jsonb,'');
insert into learning.lesson_resources(lesson_id,kind,reference,revision) values ('acm-directed','oj','207:dependency-build-order','catalog-v1');
insert into learning.path_lessons(id,path_id,title,objective,position,reading_note_id,stage,experiment_plan,experiment_setup) values ('acm-dijkstra','algorithm-foundations','Nonnegative Weighted Shortest Paths','从等权 BFS 过渡到非负权最短路，区分发现与最小距离确定。',17,(select id from learning.notes where title='ACM Curriculum — Nonnegative Weighted Shortest Paths' and deleted_at is null),'06 · Graph Models','["手算三个节点的候选路径并记录 dist。", "打印每次 heap 弹出的距离和一次松弛。", "制造过期堆条目，解释为何跳过而不重复扩展。", "测试零权、不可达、源终点相同，确认 OJ 208 实际边方向合同。"]'::jsonb,'');
insert into learning.lesson_resources(lesson_id,kind,reference,revision) values ('acm-dijkstra','oj','208:cheapest-network-route','catalog-v1');
insert into learning.path_lessons(id,path_id,title,objective,position,reading_note_id,stage,experiment_plan,experiment_setup) values ('acm-merge-sort','algorithm-foundations','Sorting and Divide-and-Conquer','通过划分、递归与合并理解排序，不把递归自动当回溯。',18,(select id from learning.notes where title='ACM Curriculum — Sorting and Divide-and-Conquer' and deleted_at is null),'07 · Common Exam Patterns','["只合并两个已经有序的短数组，不写递归。", "加入空段、一侧提前用尽和重复值，打印两个指针。", "接上递归拆分，核对每次返回的区间已排序。", "与内置 sorted 作小数据对照；比较切片与索引实现的分配。"]'::jsonb,'');
insert into learning.lesson_resources(lesson_id,kind,reference,revision) values ('acm-merge-sort','oj','163:merge-sort','catalog-v1');
insert into learning.path_lessons(id,path_id,title,objective,position,reading_note_id,stage,experiment_plan,experiment_setup) values ('acm-binary-search','algorithm-foundations','Binary Search and Boundary Invariants','在有序数据中维护候选区间，稳定处理区间收缩和未找到。',19,(select id from learning.notes where title='ACM Curriculum — Binary Search and Boundary Invariants' and deleted_at is null),'07 · Common Exam Patterns','["只手算闭区间或半开区间中的一种，写清停止条件。", "打印每轮 l/r/mid，核对范围严格变小。", "验证单元素、首尾命中、未找到和重复值合同。", "额外推导第一个 >=target 的边界，不混进本题返回要求。"]'::jsonb,'');
insert into learning.lesson_resources(lesson_id,kind,reference,revision) values ('acm-binary-search','oj','27:binary-search','catalog-v1');
insert into learning.path_lessons(id,path_id,title,objective,position,reading_note_id,stage,experiment_plan,experiment_setup) values ('acm-two-pointers','algorithm-foundations','Two Pointers on Sorted Data','通过单调性解释左右指针移动，而不是碰运气调整下标。',20,(select id from learning.notes where title='ACM Curriculum — Two Pointers on Sorted Data' and deleted_at is null),'07 · Common Exam Patterns','["列出所有两数对，标记有序性带来的排除范围。", "只打印 left/right/sum，解释每次移动的理由。", "测试负数、重复值、临界位置，保证不能使用同一元素两次。", "按题目要求输出位置，比较无序哈希法与排序后丢失原索引的问题。"]'::jsonb,'');
insert into learning.lesson_resources(lesson_id,kind,reference,revision) values ('acm-two-pointers','oj','11:two-sum-ii-input-array-is-sorted','catalog-v1');
insert into learning.path_lessons(id,path_id,title,objective,position,reading_note_id,stage,experiment_plan,experiment_setup) values ('acm-sliding-window','algorithm-foundations','Sliding Window and Validity','维护连续窗口与合法条件，区分缩窗口和更新最优值。',21,(select id from learning.notes where title='ACM Curriculum — Sliding Window and Validity' and deleted_at is null),'07 · Common Exam Patterns','["暴力枚举短字符串子串，记录合法性与最大长度。", "用频次表打印加入右端与移除左端，先保持合法再更新答案。", "测试空串（若题面允许）、全重复、包含空格和多次重复。", "与暴力对照，说明负数区间和为什么不能照搬窗口单调性。"]'::jsonb,'');
insert into learning.lesson_resources(lesson_id,kind,reference,revision) values ('acm-sliding-window','oj','16:longest-substring-without-repeating-characters','catalog-v1');
insert into learning.path_lessons(id,path_id,title,objective,position,reading_note_id,stage,experiment_plan,experiment_setup) values ('acm-hashing','algorithm-foundations','Hash Maps and Searchable History','用值到位置的映射查询补数，区分键、次数和索引。',22,(select id from learning.notes where title='ACM Curriculum — Hash Maps and Searchable History' and deleted_at is null),'07 · Common Exam Patterns','["先写所有对的暴力枚举，记录所需输出是值还是位置。", "打印历史字典，查询当前补数后才登记本轮索引。", "测试重复值、负数与合法解位置在两端。", "扩展对比出现次数问题，但保留本题的索引输出合同。"]'::jsonb,'');
insert into learning.lesson_resources(lesson_id,kind,reference,revision) values ('acm-hashing','oj','3:two-sum','catalog-v1');
insert into learning.path_lessons(id,path_id,title,objective,position,reading_note_id,stage,experiment_plan,experiment_setup) values ('acm-stack','algorithm-foundations','Stacks and Nested Structure','用未匹配左括号栈识别嵌套，而不是只比较字符数量。',23,(select id from learning.notes where title='ACM Curriculum — Stacks and Nested Structure' and deleted_at is null),'07 · Common Exam Patterns','["手写每个字符后的栈内容，不写代码。", "实现 push/match/pop 小步骤，输出失败的具体位置。", "测试右括号开头、剩余左括号、多类型嵌套。", "与合法括号的回溯生成对比：判断给定串和生成全部答案不同。"]'::jsonb,'');
insert into learning.lesson_resources(lesson_id,kind,reference,revision) values ('acm-stack','oj','21:valid-parentheses','catalog-v1');
insert into learning.path_lessons(id,path_id,title,objective,position,reading_note_id,stage,experiment_plan,experiment_setup) values ('acm-monotonic-stack','algorithm-foundations','Monotonic Stacks','保存待解答的位置，理解某个新值如何解决多个旧问题。',24,(select id from learning.notes where title='ACM Curriculum — Monotonic Stacks' and deleted_at is null),'07 · Common Exam Patterns','["暴力向右寻找首次更高，作为小数据 oracle。", "只记录栈下标和对应温度，观察单调性。", "打印当前值连续弹出的多个位置及距离。", "测试严格递减、相等温度、末尾最大，核对没有更高的默认输出。"]'::jsonb,'');
insert into learning.lesson_resources(lesson_id,kind,reference,revision) values ('acm-monotonic-stack','oj','24:daily-temperatures','catalog-v1');
insert into learning.path_lessons(id,path_id,title,objective,position,reading_note_id,stage,experiment_plan,experiment_setup) values ('acm-heap','algorithm-foundations','Heaps and Running Top-K','用大小为 k 的小顶堆维护目前最大的 k 项，说明堆顶含义。',25,(select id from learning.notes where title='ACM Curriculum — Heaps and Running Top-K' and deleted_at is null),'07 · Common Exam Patterns','["每次加入后用完整排序求基准答案。", "维护最多 k 项的 heap，打印内容和堆顶意义。", "测试重复值、负数、k=1、数据不足 k。", "把每步答案一次性按实际 OJ 规则输出，比较全部排序的代价。"]'::jsonb,'');
insert into learning.lesson_resources(lesson_id,kind,reference,revision) values ('acm-heap','oj','204:running-kth-largest','catalog-v1');
insert into learning.path_lessons(id,path_id,title,objective,position,reading_note_id,stage,experiment_plan,experiment_setup) values ('acm-greedy-intervals','algorithm-foundations','Greedy Interval Selection','通过最早结束的选择理解贪心证明，区分求删除数量与合并区间。',26,(select id from learning.notes where title='ACM Curriculum — Greedy Interval Selection' and deleted_at is null),'08 · Optimization and DP','["枚举少量区间子集，判断互不重叠并找到最优保留数。", "按 end 排序，逐步记录最后结束点与保留集合。", "用反例检查“选最长”或“开始最早”的错误策略。", "测试同起点、同终点和端点接触，核对删除数输出。"]'::jsonb,'');
insert into learning.lesson_resources(lesson_id,kind,reference,revision) values ('acm-greedy-intervals','oj','132:non-overlapping-intervals','catalog-v1');
insert into learning.path_lessons(id,path_id,title,objective,position,reading_note_id,stage,experiment_plan,experiment_setup) values ('acm-linear-dp','algorithm-foundations','Linear DP and Adjacent Constraints','在一维走格子基础上，给状态加入相邻不能同时选的约束。',27,(select id from learning.notes where title='ACM Curriculum — Linear DP and Adjacent Constraints' and deleted_at is null),'08 · Optimization and DP','["画选/不选树，排除相邻都选的分支。", "手填每个前缀最优值，标注选最后一间与不选两种来源。", "用 memo 与 bottom-up 核对小数据。", "压缩滚动状态，测试单元素与两个元素，环形房屋留作另题。"]'::jsonb,'');
insert into learning.lesson_resources(lesson_id,kind,reference,revision) values ('acm-linear-dp','oj','101:house-robber','catalog-v1');
insert into learning.path_lessons(id,path_id,title,objective,position,reading_note_id,stage,experiment_plan,experiment_setup) values ('acm-unbounded-knapsack','algorithm-foundations','Unbounded Knapsack and Minimum Coins','区分物品最多一次与可重复使用，明确最少数量和方案计数的目标。',28,(select id from learning.notes where title='ACM Curriculum — Unbounded Knapsack and Minimum Coins' and deleted_at is null),'08 · Optimization and DP','["枚举很小金额的选择，找出最少硬币数。", "填 dp[0..target]，打印不可达状态与前驱来源。", "用不含 1 的面额验证无解；对照 0/1 容量倒序的语义。", "独立解析 OJ 的 n/target 和正面额，输出最少数或 -1。"]'::jsonb,'');
insert into learning.lesson_resources(lesson_id,kind,reference,revision) values ('acm-unbounded-knapsack','oj','209:minimum-coins','catalog-v1');
insert into learning.path_lessons(id,path_id,title,objective,position,reading_note_id,stage,experiment_plan,experiment_setup) values ('acm-grid-min-cost','algorithm-foundations','Grid DP with Obstacles and Costs','将二维走格子的方案数改成最小代价，同时处理障碍和不可达。',29,(select id from learning.notes where title='ACM Curriculum — Grid DP with Obstacles and Costs' and deleted_at is null),'08 · Optimization and DP','["只处理无障碍表，手算每格最小代价。", "加入障碍，用 infinity 表示不可达并观察后续传播。", "核对起点或终点被阻挡、单行单列和无路情况。", "用小网格枚举允许方向的路径，比较 DP 结果再按 OJ 输出。"]'::jsonb,'');
insert into learning.lesson_resources(lesson_id,kind,reference,revision) values ('acm-grid-min-cost','oj','210:blocked-grid-minimum-cost','catalog-v1');
insert into learning.path_lessons(id,path_id,title,objective,position,reading_note_id,stage,experiment_plan,experiment_setup) values ('acm-lis','algorithm-foundations','Sequence DP: Longest Increasing Subsequence','区别子串与子序列，用以位置结尾的状态建立序列 DP。',30,(select id from learning.notes where title='ACM Curriculum — Sequence DP: Longest Increasing Subsequence' and deleted_at is null),'08 · Optimization and DP','["枚举小数组子序列，区分保持原顺序和连续要求。", "逐项写 dp，并打印可接上的 earlier j。", "测试下降序列、相等值、负数和最优不在末尾。", "与暴力对照；二分 tails 只作后续扩展，不把 tails 当实际完整答案。"]'::jsonb,'');
insert into learning.lesson_resources(lesson_id,kind,reference,revision) values ('acm-lis','oj','109:longest-increasing-subsequence','catalog-v1');
insert into learning.path_lessons(id,path_id,title,objective,position,reading_note_id,stage,experiment_plan,experiment_setup) values ('acm-lcs','algorithm-foundations','Two-Sequence DP: LCS','使用两段前缀定义二维状态，比较字符相等与不等的来源。',31,(select id from learning.notes where title='ACM Curriculum — Two-Sequence DP: LCS' and deleted_at is null),'08 · Optimization and DP','["列出短串所有子序列，找共同者作基准。", "画带空前缀的二维表并填写首行首列。", "逐格标末尾字符与来源方向。", "测试完全不同、完全相同、重复字符，解释答案位置与滚动限制。"]'::jsonb,'');
insert into learning.lesson_resources(lesson_id,kind,reference,revision) values ('acm-lcs','oj','112:longest-common-subsequence','catalog-v1');
insert into learning.path_lessons(id,path_id,title,objective,position,reading_note_id,stage,experiment_plan,experiment_setup) values ('acm-edit-distance','algorithm-foundations','Edit Distance and Operation Costs','在两个前缀之间比较插入、删除、替换，理解操作如何改变状态。',32,(select id from learning.notes where title='ACM Curriculum — Edit Distance and Operation Costs' and deleted_at is null),'08 · Optimization and DP','["对短串手写每种操作后的两个剩余前缀。", "填写零行零列，解释它们不是全部 0。", "逐格打印三种候选代价并核对字符相等的 0 成本。", "与 LCS 对照目标差别；按 OJ 字符串 token 合同完整读写。"]'::jsonb,'');
insert into learning.lesson_resources(lesson_id,kind,reference,revision) values ('acm-edit-distance','oj','119:edit-distance','catalog-v1');
insert into learning.path_lessons(id,path_id,title,objective,position,reading_note_id,stage,experiment_plan,experiment_setup) values ('acm-prefix-2d','algorithm-foundations','Two-Dimensional Prefix Sums','为矩形查询画重叠区域，区分二维聚合与走格子 DP。',33,(select id from learning.notes where title='ACM Curriculum — Two-Dimensional Prefix Sums' and deleted_at is null),'08 · Optimization and DP','["只暴力遍历一个 [top,bottom)×[left,right) 矩形求和。", "填带零行零列的前缀，画每格覆盖范围。", "给查询公式涂四块颜色解释加减，核对单格。", "测试单行单列、负数和多查询，再按 OJ 的四个边界顺序读入。"]'::jsonb,'');
insert into learning.lesson_resources(lesson_id,kind,reference,revision) values ('acm-prefix-2d','oj','194:two-dimensional-range-sum-queries','catalog-v1');
insert into learning.path_lessons(id,path_id,title,objective,position,reading_note_id,stage,experiment_plan,experiment_setup) values ('acm-interval-dp','algorithm-foundations','Interval DP','用区间长度安排依赖，理解“最后一个选择”如何分离两边。',34,(select id from learning.notes where title='ACM Curriculum — Interval DP' and deleted_at is null),'09 · Optional Advanced Patterns','["暴力枚举三个以内气球的戳破顺序与邻居变化。", "加入两侧哨兵，标出当前开区间与外端点。", "固定最后 k，打印左右子问题和本次得分。", "按长度填表，与小规模暴力核对后再写 OJ。"]'::jsonb,'');
insert into learning.lesson_resources(lesson_id,kind,reference,revision) values ('acm-interval-dp','oj','120:burst-balloons','catalog-v1');
insert into learning.path_lessons(id,path_id,title,objective,position,reading_note_id,stage,experiment_plan,experiment_setup) values ('acm-tree-dp','algorithm-foundations','Tree DP and Returned Contributions','区分返回给父节点的单支贡献和在本节点闭合的完整路径。',35,(select id from learning.notes where title='ACM Curriculum — Tree DP and Returned Contributions' and deleted_at is null),'09 · Optional Advanced Patterns','["在三个节点树里手画所有简单路径。", "给每个子树写返回单支贡献与当前完整候选两列。", "打印递归返回，说明负贡献为何可不接但节点答案仍需考虑。", "测试全负、单节点和最优不经根，按题面解析 null。"]'::jsonb,'');
insert into learning.lesson_resources(lesson_id,kind,reference,revision) values ('acm-tree-dp','oj','58:binary-tree-maximum-path-sum','catalog-v1');
insert into learning.path_lessons(id,path_id,title,objective,position,reading_note_id,stage,experiment_plan,experiment_setup) values ('acm-bit-operations','algorithm-foundations','Bit Operations and Bit Counts','理解整数二进制位、掩码和最低置位，不把位运算当不可解释的技巧。',36,(select id from learning.notes where title='ACM Curriculum — Bit Operations and Bit Counts' and deleted_at is null),'09 · Optional Advanced Patterns','["把 0..15 逐个转二进制，预测置位数量。", "逐位扫描并打印 mask，核对手算结果。", "用清最低 1 的过程比较循环次数。", "核对题目的无符号/位宽要求，再做 0、单个 1、全 1 边界。"]'::jsonb,'');
insert into learning.lesson_resources(lesson_id,kind,reference,revision) values ('acm-bit-operations','oj','145:number-of-1-bits','catalog-v1');
insert into learning.path_lessons(id,path_id,title,objective,position,reading_note_id,stage,experiment_plan,experiment_setup) values ('acm-trie','algorithm-foundations','Trie and Prefix Queries','分清字符串路径存在与完整单词终止，认识前缀树。',37,(select id from learning.notes where title='ACM Curriculum — Trie and Prefix Queries' and deleted_at is null),'09 · Optional Advanced Patterns','["手画 apple/app 的共享路径与结束标记。", "只写插入小机制，打印是否创建新节点。", "分别写 search 和 starts_with，验证路径存在却不终止。", "读 OJ 的操作流，按每次操作的输出合同生成结果。"]'::jsonb,'');
insert into learning.lesson_resources(lesson_id,kind,reference,revision) values ('acm-trie','oj','77:implement-trie-prefix-tree','catalog-v1');
insert into learning.path_lessons(id,path_id,title,objective,position,reading_note_id,stage,experiment_plan,experiment_setup) values ('acm-mst','algorithm-foundations','Minimum Spanning Trees','区别连通全部节点的最小总边权与从起点出发的最短路。',38,(select id from learning.notes where title='ACM Curriculum — Minimum Spanning Trees' and deleted_at is null),'09 · Optional Advanced Patterns','["小图枚举连接所有点且无环的边集，比较总权重。", "用 Prim 记录树内点与每个树外点的最便宜连接。", "每次加入最小代价点并更新候选，与手算核对。", "对比 Dijkstra 中 dist 的不同含义；单点、重复坐标以 OJ 合同处理。"]'::jsonb,'');
insert into learning.lesson_resources(lesson_id,kind,reference,revision) values ('acm-mst','oj','95:min-cost-to-connect-all-points','catalog-v1');
insert into learning.learning_paths(id,title,objective,revision,subject,overview_note_id) values ('sql-foundations','SQL — Query Practice','Learn query contracts using synthetic in-memory data, expected-row comparison and explicit explanations.',1,'sql',(select id from learning.notes where title='SQL Curriculum — Roadmap' and deleted_at is null));
insert into learning.path_lessons(id,path_id,title,objective,position,reading_note_id,stage,experiment_plan,experiment_setup) values ('sql-select','sql-foundations','SELECT, Filters and NULL','理解投影、筛选、排序与 NULL，输出可比较的结果行。',0,(select id from learning.notes where title='SQL Curriculum — SELECT, Filters and NULL' and deleted_at is null),'01 · Query Basics','["检查 fixture 的四个学生，预测 score >=80 的名字与分数。", "查询并以列表打印 fetchall()；按 id 排序核对 Ada 90、Di 80。", "分别筛选 NULL 和非 NULL，比较 = NULL 的结果。", "改变边界为 >=90、>90，解释输出变化。"]'::jsonb,'import sqlite3
INSERT INTO departments VALUES (1, ''Math''), (2, ''CS''), (3, ''History'');
INSERT INTO students VALUES (1, ''Ada'', 1, 90), (2, ''Bo'', 2, 60), (3, ''Cy'', 1, NULL), (4, ''Di'', 2, 80);
INSERT INTO orders VALUES (1, 1, 20), (2, 1, 30), (3, 2, 10), (4, 4, 40);
insert into learning.path_lessons(id,path_id,title,objective,position,reading_note_id,stage,experiment_plan,experiment_setup) values ('sql-group','sql-foundations','Aggregation, GROUP BY and HAVING','区分行筛选与分组筛选，理解聚合中的 NULL。',1,(select id from learning.notes where title='SQL Curriculum — Aggregation, GROUP BY and HAVING' and deleted_at is null),'01 · Query Basics','["按 department_id 手算人数、有效分数人数和平均分。", "写 GROUP BY 查询，按部门排序核对结果。", "用 HAVING 只保留有效分数人数至少 2 的组。", "对比先 WHERE score>=80 与分组后 HAVING AVG(score)>=80 的区别。"]'::jsonb,'import sqlite3
INSERT INTO departments VALUES (1, ''Math''), (2, ''CS''), (3, ''History'');
INSERT INTO students VALUES (1, ''Ada'', 1, 90), (2, ''Bo'', 2, 60), (3, ''Cy'', 1, NULL), (4, ''Di'', 2, 80);
INSERT INTO orders VALUES (1, 1, 20), (2, 1, 30), (3, 2, 10), (4, 4, 40);
insert into learning.path_lessons(id,path_id,title,objective,position,reading_note_id,stage,experiment_plan,experiment_setup) values ('sql-join','sql-foundations','JOIN, Missing Rows and Multiplicity','理解匹配条件、连接行数与缺失匹配，不把 LEFT JOIN 写成隐式 INNER JOIN。',2,(select id from learning.notes where title='SQL Curriculum — JOIN, Missing Rows and Multiplicity' and deleted_at is null),'02 · Relationships','["手画每名学生对应订单，预测 LEFT JOIN 行数。", "先打印学生与订单的连接行，不做聚合。", "按学生聚合订单 total，并用 COALESCE 给无订单者 0。", "移动右表条件到 ON 或 WHERE，对比 Cy 是否仍保留。"]'::jsonb,'import sqlite3
INSERT INTO departments VALUES (1, ''Math''), (2, ''CS''), (3, ''History'');
INSERT INTO students VALUES (1, ''Ada'', 1, 90), (2, ''Bo'', 2, 60), (3, ''Cy'', 1, NULL), (4, ''Di'', 2, 80);
INSERT INTO orders VALUES (1, 1, 20), (2, 1, 30), (3, 2, 10), (4, 4, 40);
insert into learning.path_lessons(id,path_id,title,objective,position,reading_note_id,stage,experiment_plan,experiment_setup) values ('sql-subquery','sql-foundations','Subqueries and EXISTS','区分存在性筛选和连接展开，理解 NOT IN 中的 NULL 风险。',3,(select id from learning.notes where title='SQL Curriculum — Subqueries and EXISTS' and deleted_at is null),'02 · Relationships','["先列至少一份 total>20 订单的学生：Ada 和 Di。", "用 EXISTS 实现存在性筛选，按 id 核对唯一学生。", "改成没有订单的 NOT EXISTS，核对 Cy。", "构造含 NULL 的小值表比较 NOT IN 与 NOT EXISTS，不修改 fixture 原表。"]'::jsonb,'import sqlite3
INSERT INTO departments VALUES (1, ''Math''), (2, ''CS''), (3, ''History'');
INSERT INTO students VALUES (1, ''Ada'', 1, 90), (2, ''Bo'', 2, 60), (3, ''Cy'', 1, NULL), (4, ''Di'', 2, 80);
INSERT INTO orders VALUES (1, 1, 20), (2, 1, 30), (3, 2, 10), (4, 4, 40);
insert into learning.path_lessons(id,path_id,title,objective,position,reading_note_id,stage,experiment_plan,experiment_setup) values ('sql-window','sql-foundations','Window Functions and Ranking','区分保留原行的窗口计算与减少行数的 GROUP BY。',4,(select id from learning.notes where title='SQL Curriculum — Window Functions and Ranking' and deleted_at is null),'03 · Query Patterns','["先只用有效 score，手排 Ada90、Di80、Bo60。", "查询 ROW_NUMBER 按 score降序、id升序，核对 1/2/3。", "在独立临时表复制一份80分，比较三种排名的并列行为。", "按订单 id 做累计 total，明确 ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW。"]'::jsonb,'import sqlite3
INSERT INTO departments VALUES (1, ''Math''), (2, ''CS''), (3, ''History'');
INSERT INTO students VALUES (1, ''Ada'', 1, 90), (2, ''Bo'', 2, 60), (3, ''Cy'', 1, NULL), (4, ''Di'', 2, 80);
INSERT INTO orders VALUES (1, 1, 20), (2, 1, 30), (3, 2, 10), (4, 4, 40);
insert into learning.path_lessons(id,path_id,title,objective,position,reading_note_id,stage,experiment_plan,experiment_setup) values ('sql-transactions','sql-foundations','Transactions and Query Plans','在内存练习中观察提交、回滚与索引，不接触生产业务表。',5,(select id from learning.notes where title='SQL Curriculum — Transactions and Query Plans' and deleted_at is null),'03 · Query Patterns','["先 commit 初始 fixture，读出 Ada score=90。", "显式开始事务把 Ada改为95，在事务内查询；rollback后核对90。", "为 score 创建索引，检查筛选 score=80 的 plan 与结果。", "说明数据库关闭后内存练习不保留，复制观察与解释回课程检查点。"]'::jsonb,'import sqlite3
INSERT INTO departments VALUES (1, ''Math''), (2, ''CS''), (3, ''History'');
INSERT INTO students VALUES (1, ''Ada'', 1, 90), (2, ''Bo'', 2, 60), (3, ''Cy'', 1, NULL), (4, ''Di'', 2, 80);
INSERT INTO orders VALUES (1, 1, 20), (2, 1, 30), (3, 2, 10), (4, 4, 40);
