-- Subject-based learning composition. Existing learner evidence and resource identities are preserved.
alter table learning.learning_paths add column subject text not null default 'algorithms' check (subject in ('algorithms','sql'));
alter table learning.learning_paths add column overview_note_id bigint references learning.notes(id);
alter table learning.path_lessons add column stage text not null default '';
alter table learning.path_lessons add column experiment_plan jsonb not null default '[]' check (jsonb_typeof(experiment_plan)='array' and jsonb_array_length(experiment_plan)<=12);
alter table learning.path_lessons add column experiment_setup text not null default '' check (length(experiment_setup)<=20000);
